class Gadget {
    #batteryLevel;

    constructor(name, initialBattery) {
        this.name = name;
        this.#batteryLevel = this.#clampBatteryLevel(initialBattery);
    }

    #clampBatteryLevel(level) {
        let clampedLevel = level;
        if (clampedLevel < 0) {
            clampedLevel = 0;
        } else if (clampedLevel > 100) {
            clampedLevel = 100;
        }
        return clampedLevel;
    }

    charge(amount) {
        if (typeof amount !== 'number' || amount <= 0 || !Number.isFinite(amount)) {
            return;
        }

        this.#batteryLevel = this.#clampBatteryLevel(this.#batteryLevel + amount);
    }

    getBatteryLevel() {
        return this.#batteryLevel;
    }
}

class Smartphone extends Gadget {
    constructor(name, initialBattery, screenSize, os) {
        super(name, initialBattery);
        this.screenSize = screenSize;
        this.operatingSystem = os;
    }

    displayInfo() {
        let infoString = this.name + " (Battery: " + this.getBatteryLevel() + "%)";
        infoString += " - Screen: " + this.screenSize + "in, OS: " + this.operatingSystem;
        return infoString;
    }
}

class Smartwatch extends Gadget {
    constructor(name, initialBattery, strapMaterial, hasHRMonitor) {
        super(name, initialBattery);
        this.strapMaterial = strapMaterial;
        this.hasHRMonitor = hasHRMonitor;
    }

    displayInfo() {
        const hrMonitorStatus = this.hasHRMonitor ? "Yes" : "No";
        let output = this.name;
        output += " (Battery: " + this.getBatteryLevel() + "%)";
        output += " - Strap: " + this.strapMaterial;
        output += ", HR Monitor: " + hrMonitorStatus;
        return output;
    }
}

